  1	// FileServerService handles HTTP file serving with proper range request support.
  2	type FileServerService struct {
  3		Profile       *profile.Profile
  4		Store         *store.Store
  5		authenticator *auth.Authenticator
  6	
  7		// thumbnailSemaphore limits concurrent thumbnail generation.
  8		thumbnailSemaphore *semaphore.Weighted
  9	}
 10	
 11	// NewFileServerService creates a new file server service.
 12	func NewFileServerService(profile *profile.Profile, store *store.Store, secret string) *FileServerService {
 13		return &FileServerService{
 14			Profile:            profile,
 15			Store:              store,
 16			authenticator:      auth.NewAuthenticator(store, secret),
 17			thumbnailSemaphore: semaphore.NewWeighted(maxConcurrentThumbnails),
 18		}
 19	}
 20	
 21	// RegisterRoutes registers HTTP file serving routes.
 22	func (s *FileServerService) RegisterRoutes(echoServer *echo.Echo) {
 23		fileGroup := echoServer.Group("/file")
 24		fileGroup.GET("/attachments/:uid/:filename", s.serveAttachmentFile)
 25		fileGroup.GET("/users/:identifier/avatar", s.serveUserAvatar)
 26	}
 27	
 28	// =============================================================================
 29	// HTTP Handlers
 30	// =============================================================================
 31	
 32	// serveAttachmentFile serves attachment binary content using native HTTP.
 33	func (s *FileServerService) serveAttachmentFile(c *echo.Context) error {
 34		ctx := c.Request().Context()
 35		uid := c.Param("uid")
 36		wantThumbnail := c.QueryParam("thumbnail") == "true"
 37		wantMotion := c.QueryParam("motion") == "true"
 38	
 39		attachment, err := s.Store.GetAttachment(ctx, &store.FindAttachment{
 40			UID:     &uid,
 41			GetBlob: true,
 42		})
 43		if err != nil {
 44			return echo.NewHTTPError(http.StatusInternalServerError, "failed to get attachment").Wrap(err)
 45		}
 46		if attachment == nil {
 47			return echo.NewHTTPError(http.StatusNotFound, "attachment not found")
 48		}
 49	
 50		if err := s.checkAttachmentPermission(ctx, c, attachment); err != nil {
 51			return err
 52		}
 53	
 54		if wantMotion {
 55			return s.serveMotionClip(c, attachment)
 56		}
 57	
 58		contentType := s.sanitizeContentType(attachment.Type)
 59	
 60		// Stream video/audio to avoid loading entire file into memory.
 61		if isMediaType(attachment.Type) {
 62			return s.serveMediaStream(c, attachment, contentType)
 63		}
 64	
 65		return s.serveStaticFile(c, attachment, contentType, wantThumbnail)
 66	}
 67	
 68	// serveUserAvatar serves user avatar images.
 69	func (s *FileServerService) serveUserAvatar(c *echo.Context) error {
 70		ctx := c.Request().Context()
 71	
 72		// On a private instance (no InstanceURL), avatars are not exposed to anonymous
 73		// visitors; a valid session, access token, or PAT is required.
 74		if !s.Profile.AllowAnonymous() {
 75			viewer, err := s.getCurrentUser(ctx, c)
 76			if err != nil {
 77				return echo.NewHTTPError(http.StatusInternalServerError, "failed to get current user").Wrap(err)
 78			}
 79			if viewer == nil {
 80				return echo.NewHTTPError(http.StatusUnauthorized, "unauthorized access")
 81			}
 82		}
 83	
 84		identifier := c.Param("identifier")
 85	
 86		user, err := s.getUserByUsername(ctx, identifier)
 87		if err != nil {
 88			return echo.NewHTTPError(http.StatusInternalServerError, "failed to get user").Wrap(err)
 89		}
 90		if user == nil {
 91			return echo.NewHTTPError(http.StatusNotFound, "user not found")
 92		}
 93		if user.AvatarURL == "" {
 94			return echo.NewHTTPError(http.StatusNotFound, "avatar not found")
 95		}
 96	
 97		imageType, imageData, err := s.parseDataURI(user.AvatarURL)
 98		if err != nil {
 99			return echo.NewHTTPError(http.StatusInternalServerError, "failed to parse avatar data").Wrap(err)
100		}
101	
102		if !avatarAllowedTypes[imageType] {
103			return echo.NewHTTPError(http.StatusBadRequest, "invalid avatar image type")
104		}
105	
106		setSecurityHeaders(c)
107		c.Response().Header().Set(echo.HeaderContentType, imageType)
108		c.Response().Header().Set(echo.HeaderCacheControl, cacheMaxAge)
109	
110		return c.Blob(http.StatusOK, imageType, imageData)
111	}
112	
113	// =============================================================================
114	// File Serving Methods
115	// =============================================================================
116

